#!/bin/bash
set -uo pipefail
PIN=e47afdde7fbf624eecf68b3d115498702f6d437f
git fetch -q origin 2>/dev/null || true
CUR=$(git rev-parse HEAD)
if [ "$CUR" != "$PIN" ]; then echo "PIN: was $CUR"; git checkout -f -q "$PIN" || { echo PIN-FAILED; exit 3; }; fi
mkdir -p src/v2/test/claim/manual
echo "" | base64 -d > src/v2/test/claim/manual/record_under_unary_probe_tmp.dag
echo STEP build; date -u +%H:%M:%S
cargo build --release -p v1-compiler --bin claim_batch 2>&1 | tail -1
./target/release/claim_batch --source-root src --source-root src/v1 --source-root src/v2 --source-root dag   --entry src/v2/test/claim/manual/record_under_unary_probe_tmp.dag --function record_under_unary_probe_reports > /tmp/rp2.log 2>&1
echo "probe rc=$?"
sed -n '/FAIL record_under_unary_probe_reports/,/\[witness\]/p' /tmp/rp2.log | cut -c1-260
rm -f src/v2/test/claim/manual/record_under_unary_probe_tmp.dag
echo "=== DONE ==="
